-- Uitvoeren na 20260908062000_agency_suppliers.sql. Alles wordt teruggedraaid.
BEGIN;CREATE TEMP TABLE ast AS SELECT gen_random_uuid() owner_id,gen_random_uuid() workspace_id,gen_random_uuid() trip_id,gen_random_uuid() other_owner,gen_random_uuid() other_workspace,gen_random_uuid() other_trip;
INSERT INTO auth.users(id,email,email_confirmed_at) SELECT owner_id,'supplier-owner@example.invalid',now() FROM ast UNION ALL SELECT other_owner,'supplier-other@example.invalid',now() FROM ast;
INSERT INTO public.workspaces(user_id,workspace_uuid,plan,data) SELECT owner_id,workspace_id,'agency','{}'::JSONB FROM ast UNION ALL SELECT other_owner,other_workspace,'agency','{}'::JSONB FROM ast;
INSERT INTO public.trips(workspace_user_id,workspace_uuid,id,trip_uuid,name) SELECT owner_id,workspace_id,trip_id::TEXT,trip_id,'Leveranciersreis' FROM ast UNION ALL SELECT other_owner,other_workspace,other_trip::TEXT,other_trip,'Andere reis' FROM ast;
DO $$ DECLARE o UUID;w UUID;t UUID;x UUID;s UUID;BEGIN SELECT owner_id,workspace_id,trip_id,other_trip INTO o,w,t,x FROM ast;SELECT public.save_agency_supplier(o,w,NULL,'{"type":"transport","name":"Testvervoerder","commissionPercent":5}'::JSONB,ARRAY[t]) INTO s;IF NOT EXISTS(SELECT 1 FROM public.agency_supplier_trips WHERE supplier_id=s AND trip_uuid=t) THEN RAISE EXCEPTION 'Reiskoppeling ontbreekt';END IF;BEGIN PERFORM public.save_agency_supplier(o,w,s,'{"type":"transport","name":"Fout"}'::JSONB,ARRAY[x]);RAISE EXCEPTION 'Workspacegrens niet bewaakt';EXCEPTION WHEN foreign_key_violation THEN NULL;END;IF NOT EXISTS(SELECT 1 FROM public.agency_suppliers WHERE id=s AND name='Testvervoerder') THEN RAISE EXCEPTION 'Mislukte wijziging niet teruggedraaid';END IF;PERFORM public.set_agency_supplier_archived(o,w,s,true);IF NOT EXISTS(SELECT 1 FROM public.agency_suppliers WHERE id=s AND status='archived') THEN RAISE EXCEPTION 'Archiveren mislukt';END IF;END $$;ROLLBACK;
